// Run workflow Refund triage and wait for its result (publish it first: invoke runs the published version)
// Node 18+ (global fetch). Run with: npx tsx swfte-call.ts  (export SWFTE_API_KEY first)
const BASE_URL = "https://api.example.test/agents";
const headers: Record<string, string> = {
  Authorization: `Bearer ${process.env.SWFTE_API_KEY}`,
  "Content-Type": "application/json",
};

async function main() {
  const res = await fetch(`${BASE_URL}/v2/workflows/wf_1/versions/1.0.0/invoke`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      "customerEmail": "example customerEmail",
      "amount": 1
    }),
  });
  if (!res.ok) throw new Error(`HTTP ${res.status}: ${await res.text()}`);
  const { executionId } = await res.json();
  let status = "PENDING";
  let result: any;
  while (["PENDING", "RUNNING", "QUEUED"].includes(status)) {
    await new Promise((resolve) => setTimeout(resolve, 2000));
    const poll = await fetch(`${BASE_URL}/v2/workflows/executions/${encodeURIComponent(executionId)}/status`, { headers });
    if (!poll.ok) throw new Error(`HTTP ${poll.status}: ${await poll.text()}`);
    result = await poll.json();
    status = result.execution?.status;
  }
  if (!["SUCCESS", "SUCCEEDED", "COMPLETED"].includes(status)) throw new Error(`Execution ${executionId} ended ${status}`);
  console.log(result.execution.outputData?.parameters?.["end_1"]);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
